class UnknownFormatError(StatementError):
    """Файл выписки нельзя прочитать: неизвестный формат, заголовок или кодировка."""


class StatementRowError(StatementError):
    """Ошибочная строка выписки (line_no всегда заполнен)."""

    def __init__(self, message: str, *, line_no: int) -> None:
        super().__init__(message, line_no=line_no)
EOF
cat > ledger/importer.py <<'EOF'
"""Импорт банковских выписок.

Поддерживаются форматы (определяются по заголовку):

    nova         date,amount,description               (разделитель ",")
    sfera        Дата;Сумма;Описание                   (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход           (разделитель ";")

Кодировка — UTF-8 (с BOM или без) либо cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field, replace
from decimal import Decimal
from typing import Iterator

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA = "nova"
SFERA = "sfera"
SFERA_SPLIT = "sfera_split"

# формат -> (разделитель, колонки в нижнем регистре)
_SCHEMAS: dict[str, tuple[str, tuple[str, ...]]] = {
    NOVA: (",", ("date", "amount", "description")),
    SFERA: (";", ("дата", "сумма", "описание")),
    SFERA_SPLIT: (";", ("дата", "описание", "приход", "расход")),
}

_SFERA_DATE = re.compile(r"^\d{2}\.\d{2}\.\d{4}$")
_SFERA_AMOUNT = re.compile(r"^[+-]?(\d{1,3}([  ]\d{3})+|\d+)(,\d{1,2})?$")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)
    format: str = NOVA
    encoding: str = "utf-8"


def normalize_description(text: str) -> str:
    """Нормализация описания для сравнения (см. rules.normalize_text)."""
    return normalize_text(text)


def _decode(data: bytes) -> tuple[str, str]:
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("cannot decode file as UTF-8 or cp1251") from exc


def _is_junk(cells: list[str]) -> bool:
    return not "".join(cells).replace(";", "").replace(",", "").strip()


def _records(text: str, delimiter: str) -> Iterator[tuple[int, list[str]]]:
    """Непустые записи с физическим номером строки, где запись начинается."""
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
    prev_end = 0
    for cells in reader:
        start = prev_end + 1
        prev_end = reader.line_num
        if not _is_junk(cells):
            yield start, cells


def _match_header(cells: list[str], columns: tuple[str, ...]) -> dict[str, int] | None:
    names = [c.strip().casefold() for c in cells]
    index: dict[str, int] = {}
    for col in columns:
        if col not in names:
